import random

def get_user_choice():
    """Get user input for their choice (rock, paper, or scissors)."""
    choices = ["rock", "paper", "scissors"]
    while True:
        user_choice = input("Enter 'rock', 'paper', or 'scissors': ").lower()
        if user_choice in choices:
            return user_choice
        else:
            print("Invalid input. Please enter 'rock', 'paper', or 'scissors'.")

def get_computer_choice():
    """Generate a random computer choice."""
    return random.choice(["rock", "paper", "scissors"])

def play_round(user_choice, computer_choice):
    """Determine the outcome of the round."""
    user_choices = {"rock": "scissors", "scissors": "paper", "paper": "rock"}
    if user_choice == computer_choice:
        print(f"It's a tie! Neither {user_choice.capitalize()} nor {computer_choice.capitalize()} wins.")
    elif user_choices[user_choice] == computer_choice:
        print(f"{user_choice.capitalize()} beats {computer_choice.capitalize()}! You win!")
    else:
        print(f"{computer_choice.capitalize()} beats {user_choice.capitalize()}! You lose!")

def play_game():
    """Play a game of rock paper scissors against the user."""
    while True:
        user_choice = get_user_choice()
        computer_choice = get_computer_choice()
        play_round(user_choice, computer_choice)
        restart = input("Do you want to play again? (yes/no): ").lower()
        if restart != "yes":
            break

if __name__ == "__main__":
    play_game()
